<script setup lang="ts">
import ActionMenu from "../../components/ActionMenu.vue";
import {Head,Link,router} from '@inertiajs/vue3';
import {reactive} from 'vue';
import AppLayout from '../../layouts/AppLayout.vue';
import Pagination from '../../components/Pagination.vue';
import {money,type PageRows} from '../../types/salesOrder';
import {progress,type Budget,type ExpenseRow,type OpsProgram} from '../../types/operations';
type Row=ExpenseRow & OpsProgram & {budget?:{fixed:Budget;variable:Budget};waiting:number;pengajuan_count:number};
const props=defineProps<{rows:PageRows<Row>;filters:Record<string,string>;counts:Record<string,number>;tab:string}>();
const f=reactive({q:'',jenis:'',status:'',tab:props.tab,...props.filters});
</script>
<template><Head title="Pengajuan Biaya"/><AppLayout title="Pengajuan Biaya"><h1>Pengajuan Biaya</h1><nav class="tabs" aria-label="Daftar biaya"><Link href="/pengajuan-biaya" :aria-current="tab==='program'?'page':undefined">Ajukan Biaya ({{counts.program}})</Link><Link href="/pengajuan-biaya?tab=pengajuan" :aria-current="tab==='pengajuan'?'page':undefined">Sudah Diajukan ({{counts.pengajuan}})</Link></nav><form class="filters" @submit.prevent="router.get('/pengajuan-biaya',f)"><label>Cari<input v-model="f.q" type="search" maxlength="100"/></label><label>Jenis<select v-model="f.jenis"><option value="">Semua</option><template v-if="tab==='program'"><option value="public">Public</option><option value="b2b">B2B</option></template><template v-else><option value="kasbon">Kasbon</option><option value="direct_payment">Direct Payment</option></template></select></label><label v-if="tab==='pengajuan'">Progres<select v-model="f.status"><option value="">Semua</option><option v-for="(label,key) in progress" :key="key" :value="key">{{label}}</option></select></label><button>Terapkan</button></form><div class="table-wrap"><table><thead><tr><th>{{tab==='program'?'Program':'No. Pengajuan'}}</th><th>{{tab==='program'?'Tim':'Program / Request By'}}</th><th>{{tab==='program'?'Budget / Aktual / Sisa':'Total'}}</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="p in rows.data" :key="p.id"><td>{{p.nomor}}<small>{{p.judul}}<br>{{p.jenis}} · {{p.tanggal || p.tgl_mulai}}<br>{{p.deskripsi}}</small></td><td v-if="tab==='program'">{{p.tim?.company}}<small>Sales {{p.tim?.sales.join(', ')}}<br>Trainer {{p.tim?.trainer}}</small></td><td v-else>{{p.program_nomor}}<small>{{p.pengaju}}</small></td><td v-if="p.budget"><p v-for="(b,key) in p.budget" :key="key">{{key==='fixed'?'Fixed':'Variable'}}: {{money(b.budget)}} / {{money(b.aktual)}} / {{money(b.sisa)}}</p></td><td v-else>{{money(p.total)}}</td><td>{{tab==='program'?(p.closed_date?'Closed':p.waiting?`${p.waiting} Waiting Approval`:p.pengajuan_count?'Berjalan':'Belum ada pengajuan'):progress[p.status]}}</td><td><ActionMenu><Link :href="tab==='program'?`/pengajuan-biaya/program/${p.id}`:`/pengajuan-biaya/pengajuan/${p.id}`">{{tab==='program'?'Lihat Pengajuan':'Lihat'}}</Link></ActionMenu></td></tr><tr v-if="!rows.data.length"><td colspan="5" class="empty">Tidak ada data sesuai akses dan filter.</td></tr></tbody></table></div><Pagination :page="rows" label="Halaman Pengajuan Biaya"/></AppLayout></template>
